{"cards": [{"node_code": "N_3dbd84416c888dac", "definition": "研究中国航空运输领域的成本构成、运价与票价制定机制、经济核算方法及财务分析，涵盖中国民航企业的具体经济实践。", "boundary": "本节点聚焦于中国航空运输的经济量化分析，包括成本结构、定价策略及财务核算。边界在于区分“经济核算”与“宏观政策”（政策归入方针政策节点）及“企业管理”（组织人事归入企业经营管理节点）。内容需明确涉及中国民航的成本数据、票价体系或经济评估。", "includes": ["中国航空运输成本构成与核算方法", "中国民航运价、票价制定及调整机制", "中国航空运输经济效益分析与财务指标"], "excludes": ["中国航空运输宏观方针政策", "中国航空运输企业组织架构与人力资源管理"], "sibling_distinctions": [{"other_code": "N_48f53e94084754bf", "rule": "本节点侧重财务数据、成本定价等经济量化指标；企业组织与经营管理侧重组织结构、业务流程及人员管理。"}, {"other_code": "N_fb6279bdb5c67c46", "rule": "本节点侧重具体的经济核算与定价实践；方针政策节点侧重国家层面的战略导向、法规条文及宏观规划。"}], "cross_boundary_rule": "涉及票价政策时，若侧重具体定价模型、成本分摊或财务影响，归入本节点；若侧重政府定价法规、市场准入政策或宏观调控方向，归入方针政策节点。"}, {"node_code": "N_48f53e94084754bf", "definition": "研究中国航空运输企业的组织架构、内部管理制度、运营流程优化及人力资源配置，涵盖中国民航企业的微观管理实践。", "boundary": "本节点聚焦于中国航空运输企业的内部管理与组织行为，包括部门设置、流程控制、绩效考核及企业文化。边界在于区分“内部管理”与“外部经济环境”（市场供需归入成本运价或宏观节点）及“宏观体制”（行业监管归入管理体制节点）。内容需明确涉及中国航空公司的具体管理案例或制度。", "includes": ["中国航空运输企业组织架构与部门职能", "中国民航企业运营流程、质量控制与安全管理", "中国航空运输企业人力资源、绩效考核及企业文化建设"], "excludes": ["中国航空运输成本核算与票价制定", "中国民航行业宏观管理体制与政策法规"], "sibling_distinctions": [{"other_code": "N_3dbd84416c888dac", "rule": "本节点侧重组织行为、流程制度及人员管理；成本运价节点侧重财务数据、定价策略及经济核算。"}, {"other_code": "N_e430803eaec0a3a3", "rule": "本节点侧重企业内部微观管理；航运管理体制侧重行业层面的政府监管、行政架构及宏观制度安排。"}], "cross_boundary_rule": "涉及企业改革时，若侧重内部组织调整、流程再造或管理创新，归入本节点；若侧重行业监管体制改革、政企关系或宏观政策调整，归入航运管理体制节点。"}, {"node_code": "N_164b1895650e39d0", "definition": "研究中国各省市及区域航空运输的经济特征、地方机场运营、区域航线网络及对地方经济的贡献，涵盖地方航空经济实践。", "boundary": "本节点聚焦于中国特定地域（省、市、区域）的航空运输经济活动，包括地方机场经济、区域航线规划及航空对地方GDP的影响。边界在于区分“地方/区域”与“全国/中央”（全国性政策或央企总部管理归入其他节点）及“纯工程技术”（机场建设技术归入工程节点）。内容需明确涉及中国特定地方的航空经济数据或案例。", "includes": ["中国各省市航空运输经济发展现状与趋势", "地方机场运营经济、区域航线网络规划", "航空运输对地方经济、旅游及产业的带动效应"], "excludes": ["中国民航全国性宏观政策与中央管理体制", "普适性的航空运输经济理论模型"], "sibling_distinctions": [{"other_code": "N_48f53e94084754bf", "rule": "本节点侧重区域/地方层面的经济特征与机场运营；企业组织与经营管理侧重单一航空公司的内部微观管理。"}, {"other_code": "N_3dbd84416c888dac", "rule": "本节点侧重区域航空经济整体及地方机场；成本运价节点侧重航空运输通用的成本定价机制及财务核算。"}], "cross_boundary_rule": "涉及地方机场时，若侧重机场作为地方基础设施的经济效益、区域航线布局，归入本节点；若侧重机场内部具体运营流程或某家航空公司在该地的分公司管理，需视具体内容，若为通用管理可归入企业经营管理，若为地方特色经济归入本节点。"}]}
